import { readFileSync } from 'fs';

const input = readFileSync(0, 'utf8');

// Validate mode argument
const mode = process.argv[2];
if (!mode || !['rounds', 'tally'].includes(mode)) {
  process.stderr.write('error: usage: cli.js rounds|tally\n');
  process.exit(2);
}

/**
 * Parse election input
 * Returns { candidates, ballots }
 */
function parseElection(input) {
  const lines = input.split('\n');

  // Drop empty tail if present
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }

  let candidates = null;
  const ballots = [];
  let candidatesDeclared = false;

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const rawLine = lines[i];
    const trimmed = rawLine.trim();

    // Ignore empty lines and comments
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue;
    }

    const parts = trimmed.split(/\s+/);
    const directive = parts[0];

    if (directive === 'candidates') {
      if (candidatesDeclared) {
        process.stderr.write(`error: line ${lineNum}: candidates must be declared once, before any ballot\n`);
        process.exit(2);
      }
      if (parts.length < 2) {
        process.stderr.write(`error: line ${lineNum}: expected candidates <name>...\n`);
        process.exit(2);
      }

      candidates = parts.slice(1);
      const seen = new Set();

      for (const name of candidates) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) {
          process.stderr.write(`error: line ${lineNum}: invalid candidate name ${name}\n`);
          process.exit(2);
        }
        if (seen.has(name)) {
          process.stderr.write(`error: line ${lineNum}: candidate ${name} is declared twice\n`);
          process.exit(2);
        }
        seen.add(name);
      }
      candidatesDeclared = true;
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        process.stderr.write(`error: line ${lineNum}: candidates must be declared once, before any ballot\n`);
        process.exit(2);
      }
      if (parts.length < 2) {
        process.stderr.write(`error: line ${lineNum}: expected ballot <count> <candidate>...\n`);
        process.exit(2);
      }

      const countStr = parts[1];
      const count = parseInt(countStr, 10);

      // Validate count: must be positive, no leading zero, no sign
      if (isNaN(count) || count <= 0 || countStr !== count.toString()) {
        process.stderr.write(`error: line ${lineNum}: count must be a positive integer\n`);
        process.exit(2);
      }

      const ballotCandidates = parts.slice(2);
      if (ballotCandidates.length === 0) {
        process.stderr.write(`error: line ${lineNum}: expected ballot <count> <candidate>...\n`);
        process.exit(2);
      }

      // Validate ballot candidates
      const candidateSet = new Set(candidates);
      const ballotSeen = new Set();

      for (const name of ballotCandidates) {
        if (!candidateSet.has(name)) {
          process.stderr.write(`error: line ${lineNum}: unknown candidate ${name}\n`);
          process.exit(2);
        }
        if (ballotSeen.has(name)) {
          process.stderr.write(`error: line ${lineNum}: candidate ${name} is repeated\n`);
          process.exit(2);
        }
        ballotSeen.add(name);
      }

      ballots.push({ count, candidates: ballotCandidates });
    } else {
      process.stderr.write(`error: line ${lineNum}: unknown directive ${directive}\n`);
      process.exit(2);
    }
  }

  // Ensure candidates were declared
  if (!candidatesDeclared) {
    process.stderr.write('error: no candidates\n');
    process.exit(2);
  }

  return { candidates, ballots };
}

/**
 * Break a tie between candidates using historical round data.
 * Compares candidates across all rounds from first to last.
 * At the first round where not all tied candidates have equal votes,
 * keep only those with the fewest votes and repeat from round 1.
 * If still tied, eliminate the one whose name sorts last by code point.
 */
function breakTie(candidates, allRoundVotes) {
  let tied = new Set(candidates);

  for (const roundVotes of allRoundVotes) {
    if (tied.size <= 1) break;

    let minRoundVotes = Infinity;
    for (const name of tied) {
      const count = roundVotes.get(name);
      if (count < minRoundVotes) {
        minRoundVotes = count;
      }
    }

    const newTied = new Set();
    for (const name of tied) {
      if (roundVotes.get(name) === minRoundVotes) {
        newTied.add(name);
      }
    }
    tied = newTied;
  }

  if (tied.size > 1) {
    // Eliminate the one whose name sorts last by code point
    let last = '';
    for (const name of tied) {
      if (name.localeCompare(last) > 0) {
        last = name;
      }
    }
    return last;
  }

  return Array.from(tied)[0];
}

/**
 * Run the instant runoff election
 */
function runElection(candidates, ballots) {
  const continuing = new Set(candidates);
  const rounds = [];

  while (true) {
    const votes = new Map();
    let exhausted = 0;

    // Initialize vote counts for all candidates
    for (const name of candidates) {
      votes.set(name, 0);
    }

    // Count votes: each ballot counts for the first continuing candidate
    for (const ballot of ballots) {
      let counted = false;
      for (const name of ballot.candidates) {
        if (continuing.has(name)) {
          votes.set(name, votes.get(name) + ballot.count);
          counted = true;
          break;
        }
      }
      if (!counted) {
        exhausted += ballot.count;
      }
    }

    // Calculate active total (ballots that count for someone)
    let activeTotal = 0;
    for (const name of continuing) {
      activeTotal += votes.get(name);
    }

    // Store round info (before elimination)
    const roundInfo = {
      votes: new Map(votes),
      exhausted,
      activeTotal,
      eliminated: null,
      continuing: new Set(continuing)
    };
    rounds.push(roundInfo);

    // Check win condition: some candidate's count × 2 > active total
    for (const name of continuing) {
      if (votes.get(name) * 2 > activeTotal) {
        return { rounds, winner: name };
      }
    }

    // Check if no winner: active total is 0
    if (activeTotal === 0) {
      return { rounds, winner: null };
    }

    // Find candidate(s) with minimum votes
    let minVotes = Infinity;
    const minCandidates = [];

    for (const name of continuing) {
      const count = votes.get(name);
      if (count < minVotes) {
        minVotes = count;
        minCandidates.length = 0;
        minCandidates.push(name);
      } else if (count === minVotes) {
        minCandidates.push(name);
      }
    }

    // Eliminate the candidate with fewest votes (or resolve tie)
    let toEliminate;
    if (minCandidates.length === 1) {
      toEliminate = minCandidates[0];
    } else {
      toEliminate = breakTie(minCandidates, rounds.map(r => r.votes));
    }

    roundInfo.eliminated = toEliminate;
    continuing.delete(toEliminate);
  }
}

// Parse and run the election
const { candidates, ballots } = parseElection(input);
const result = runElection(candidates, ballots);

// Output results
if (mode === 'rounds') {
  for (let i = 0; i < result.rounds.length; i++) {
    const round = result.rounds[i];
    const roundNum = i + 1;

    // Sort continuing candidates: by descending votes, then by ascending name
    const sortedCandidates = Array.from(round.continuing).sort((a, b) => {
      const votesDiff = round.votes.get(b) - round.votes.get(a);
      if (votesDiff !== 0) return votesDiff;
      return a.localeCompare(b);
    });

    let output = `round ${roundNum}:`;
