      output += ` ${name}=${round.votes.get(name)}`;
    }
    output += ` exhausted=${round.exhausted}`;
    process.stdout.write(output + '\n');

    if (round.eliminated) {
      process.stdout.write(`eliminated ${round.eliminated}\n`);
    }
  }
}

